def free_time_slots(intervals, day_start, day_end):
    result = []
    cur = day_start
    for s, e in intervals:
        if s > cur:
            result.append((cur, s))
        cur = max(cur, e)
    if cur < day_end:
        result.append((cur, day_end))
    return result

def next_leap_year(year):
    y = year + 1
    while not (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)):
        y += 1
    return y

def previous_leap_year(year):
    y = year - 1
    while not (y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)):
        y -= 1
    return y

def count_leap_years_in_range(y1, y2):
    def leaps_up_to(y):
        return y//4 - y//100 + y//400
    return leaps_up_to(y2) - leaps_up_to(y1-1)

def leap_years_before(year):
    y = year - 1
    if y < 1:
        return 0
    return y//4 - y//100 + y//400

def months_between(date1, date2):
    y1, m1, d1 = date1
    y2, m2, d2 = date2
    months = (y2 - y1)*12 + (m2 - m1)
    if d2 < d1:
        months -= 1
    return max(0, months)

def last_day_of_month(year, month):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    return (year, month, lengths[month-1])

def first_day_of_next_month(year, month):
    if month == 12:
        return (year+1, 1, 1)
    return (year, month+1, 1)

def previous_month(year, month):
    if month == 1:
        return (year-1, 12)
    return (year, month-1)

def next_month(year, month):
    if month == 12:
        return (year+1, 1)
    return (year, month+1)

def add_months(year, month, n):
    total = (year*12 + (month-1)) + n
    return (total//12, total%12 + 1)

def week_number_simple(year, month, day):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    doy = sum(lengths[:month-1]) + day
    return (doy - 1)//7 + 1

def weekday_name_from_index(index):
    names = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']
    return names[index % 7]

def is_weekday_name(s):
    names = {'Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'}
    return s in names

def count_weekday_occurrences(year, month, weekday):
    lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
    if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0):
        lengths[1] = 29
    t = [0,3,2,5,0,3,5,1,4,6,2,4]
    count = 0
    for day in range(1, lengths[month-1]+1):
        y = year
        m = month
        if m < 3:
            y -= 1
        w = (y + y//4 - y//100 + y//400 + t[m-1] + day) % 7
        if w == weekday:
            count += 1
    return count

def count_specific_weekday_between(date1, date2, weekday):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def doy(y, m, d):
        lengths = [31,28,31,30,31,30,31,31,30,31,30,31]
        if is_leap(y):
            lengths[1] = 29
        return sum(lengths[:m-1]) + d
    def ordinal(date):
        y, m, d = date
        return 365*(y-1) + (y-1)//4 - (y-1)//100 + (y-1)//400 + doy(y, m, d)
    def weekday_of_ordinal(o):
        return (o + 5) % 7
    o1 = ordinal(date1)
    o2 = ordinal(date2)
    total_days = o2 - o1 + 1
    full_weeks = total_days // 7
    remainder = total_days % 7
    count = full_weeks
    start_weekday = weekday_of_ordinal(o1)
    for i in range(remainder):
        if (start_weekday + i) % 7 == weekday:
            count += 1
    return count
